import type { QueryClient } from "@tanstack/react-query";
import { describe, expect, it, vi } from "vitest";
import registryJson from "../../../../services/api/internal/events/registry.json";
import { routeProjectEvent } from "./project-event-rules";

// registry.json is generated by services/api (TestRegistryIsUpToDate) from
// events.AuthzFor: every topic a client can be sent. Each one must be taken by
// a rule of EVENT_RULES, or the page would ignore that change until a reload.
interface Entry {
	topic: string;
	action: string;
	scope: string;
}
const registry = registryJson as { realtime: Entry[] };

// Topics whose rule needs a field of the payload to act; without it the rule
// passes and a broader one must still take the event.
const payloadFor = (topic: string): Record<string, unknown> => ({
	task_id: "t1",
	document_id: "d1",
	view_id: "v1",
	environment_id: "e1",
	status: "running",
	conversation_id: "c1",
	topic,
});

describe("EVENT_RULES against the event registry", () => {
	it("has a rule for every topic services/api can send to a project", () => {
		const unhandled: string[] = [];
		for (const { topic } of registry.realtime) {
			const queryClient = {
				invalidateQueries: vi.fn(),
				setQueryData: vi.fn(),
				setQueriesData: vi.fn(),
				removeQueries: vi.fn(),
			} as unknown as QueryClient;
			const rule = routeProjectEvent(
				{ queryClient, projectId: "p" },
				{ type: topic, payload: payloadFor(topic) },
			);
			if (rule === null) unhandled.push(topic);
		}
		expect(unhandled).toEqual([]);
	});

	it("is not empty", () => {
		expect(registry.realtime.length).toBeGreaterThan(50);
	});
});
